// Original Earthwing model film: 144 independently rendered 3840×2160 frames, 24 fps.
// Do not edit source files while the capture runs (Vite hot reload invalidates it).
import puppeteer from 'puppeteer-core';import fs from 'node:fs';
// Run with the local dev server running. Keep generated masters outside the repository.
const dir=process.env.ART_OUTPUT || '/tmp/earthwing-art';fs.mkdirSync(dir,{recursive:true});
const origin=process.env.ART_ORIGIN || 'http://127.0.0.1:5173';
const b=await puppeteer.launch({executablePath:process.env.CHROME_PATH || '/usr/bin/google-chrome',headless:true,protocolTimeout:600000,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-dev-shm-usage','--ignore-certificate-errors']});const results=[];
try{for(const ac of ['sr71','c172','sf50','il76']){const p=await b.newPage();await p.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await p.setViewport({width:1280,height:720});const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.evaluateOnNewDocument(()=>localStorage.setItem('sr71sim.settings',JSON.stringify({gfx:'low',gfxV3:true,gfxV7:true,rscale:.5,dynres:false,metarAuto:false,buildings:false,trees:false,clouds:0,traffic:false})));
await p.goto(origin+'/?aircraft='+ac,{waitUntil:'domcontentloaded'});await p.waitForFunction(()=>window.__sim,{timeout:150000});
const info=await p.evaluate(async(ac)=>{const S=__sim,T=S.THREE;S.state.paused=true;S.post.render=()=>{};window.requestAnimationFrame=()=>0;S.visual.root.position.set(0,0,0);S.visual.root.quaternion.identity();S.visual.root.visible=true;if(S.visual.gearGroup)S.visual.gearGroup.visible=false;if(S.visual.covers)S.visual.covers.visible=true;S.visual.model.traverse(o=>{if(o.name==='Interior')o.visible=false;});
const sc=new T.Scene();sc.background=new T.Color('#1c3449');sc.environment=S.scene.environment;sc.add(S.visual.model);sc.updateMatrixWorld(true);sc.add(new T.HemisphereLight(0xe0f4ff,0x8098aa,4));const sun=new T.DirectionalLight(0xfff2df,6);sun.position.set(15,40,20);sc.add(sun);const rim=new T.DirectionalLight(0x92cfff,3);rim.position.set(-25,12,-20);sc.add(rim);
const box=new T.Box3().setFromObject(S.visual.model),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),d=Math.max(size.x,size.y,size.z);
const cam=new T.PerspectiveCamera(35,16/9,.05,10000);cam.position.copy(center).add(new T.Vector3(d*.82,d*.50,d*.95));cam.lookAt(center);cam.zoom=ac==='c172'?2:ac==='sr71'?1.4:1;cam.updateProjectionMatrix();S.renderer.setPixelRatio(1);S.renderer.setSize(1920,1080,false);S.renderer.toneMappingExposure=1.5;S.renderer.render(sc,cam);const card=S.renderer.domElement.toDataURL('image/png');let hero=null;
if(ac==='sr71'){const mat=new T.ShaderMaterial({uniforms:{phase:{value:0}},depthWrite:false,depthTest:false,vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}',fragmentShader:`precision highp float;varying vec2 vUv;uniform float phase;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+1.),f.x),f.y);}
float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<6;i++){v+=a*n(p);p=p*2.03+13.7;a*=.5;}return v;}
void main(){vec2 uv=vUv;float h=uv.y;vec3 sky=mix(vec3(.54,.73,.84),vec3(.025,.13,.25),smoothstep(.28,1.,h));sky+=vec3(.23,.17,.10)*exp(-pow((h-.39)*10.,2.));float depth=max(.035,.47-h);vec2 p=vec2((uv.x-.5)/depth*.9,1./depth*.8);p+=vec2(sin(phase)*.3,cos(phase)*.2);float clouds=fbm(p*.85)+.23*fbm(p*3.1);float cover=smoothstep(.32,.67,clouds);vec3 cloud=mix(vec3(.23,.39,.49),vec3(.91,.96,.97),smoothstep(.3,.78,clouds));vec3 col=mix(sky,cloud,cover*(1.-smoothstep(.40,.445,h)));col=mix(col,vec3(.67,.79,.85),exp(-pow((h-.43)*26.,2.))*.7);gl_FragColor=vec4(col,1.);}`});const bg=new T.Mesh(new T.PlaneGeometry(2,2),mat);bg.frustumCulled=false;bg.renderOrder=-1000;sc.add(bg);S.renderer.setSize(3840,2160,false);cam.position.copy(center).add(new T.Vector3(d*.86,d*.48,d*1.02));cam.lookAt(center);cam.zoom=1.3;cam.setViewOffset(3840,2160,-360,-420,3840,2160);cam.updateProjectionMatrix();S.renderer.render(sc,cam);hero=S.renderer.domElement.toDataURL('image/png');window.__heroRender=(phase)=>{if(S.visual.gearGroup)S.visual.gearGroup.visible=false;if(S.visual.covers)S.visual.covers.visible=true;cam.position.copy(center).add(new T.Vector3(d*(.86+.09*Math.sin(phase)),d*(.48+.035*Math.cos(phase)),d*(1.02+.04*Math.cos(phase))));cam.lookAt(center);mat.uniforms.phase.value=phase;S.renderer.render(sc,cam);return S.renderer.domElement.toDataURL('image/jpeg',.96);};}
const gl=S.renderer.getContext(),ext=gl.getExtension('WEBGL_debug_renderer_info');return{ac,card,hero,box:size.toArray(),renderer:gl.getParameter(ext.UNMASKED_RENDERER_WEBGL),heroRaster:ac==='sr71'?[3840,2160]:null};},ac);
fs.writeFileSync(dir+'/render-'+ac+'.png',Buffer.from(info.card.split(',')[1],'base64'));delete info.card;if(info.hero)fs.writeFileSync(dir+'/hero-native-4k.png',Buffer.from(info.hero.split(',')[1],'base64'));delete info.hero;results.push({...info,errors});if(ac==='sr71'){fs.mkdirSync(dir+'/frames',{recursive:true});for(let i=0;i<144;i++){const data=await p.evaluate(phase=>__heroRender(phase),2*Math.PI*i/144);fs.writeFileSync(dir+'/frames/'+String(i).padStart(4,'0')+'.jpg',Buffer.from(data.split(',')[1],'base64'));if(i%24===0)console.log('native frame',i);}}await p.close();}
}finally{await b.close();fs.writeFileSync(dir+'/render-metadata.json',JSON.stringify(results,null,2));}
